use vstd::prelude::*;

verus! {
    /// where_fn takes three vectors of equal length:
    ///   - `condition`: Vec<bool>
    ///   - `x`:         Vec<f32>
    ///   - `y`:         Vec<f32>
    /// It returns a new Vec<f32> `result` of the same length, such that
    /// for each index i,
    ///   result[i] == if condition[i] { x[i] } else { y[i] }.
    fn where_fn(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> (result: Vec<f32>)
        requires
            // all three inputs have the same length
            condition.len() == x.len() && x.len() == y.len()
        ensures
            // output has the same length
            result.len() == condition.len(),
        ensures
            // element‐wise specification
            forall|i: usize| i < condition.len() ==>
                result[i] == if condition[i] { x[i] } else { y[i] }
    {
        let n = condition.len();
        // preallocate result buffer
        let mut result: Vec<f32> = Vec::with_capacity(n);
        let mut i: usize = 0;

        // build result by pushing one element at a time
        while i < n
            invariant
                // loop index stays in bounds
                i <= n,
                // result has grown exactly i elements so far
                result.len() == i,
                // those i elements satisfy the selection property
                forall|j: usize| j < i ==>
                    result[j] == if condition[j] { x[j] } else { y[j] },
            decreases
                // variant to prove termination
                n - i,
        {
            // select the appropriate element for index i
            let elem = if condition[i] {
                x[i]
            } else {
                y[i]
            };
            result.push(elem);
            i += 1;
        }

        result
    }
}

fn main() {
    // Example usage (not verified):
    let cond = vec![true, false, true];
    let x    = vec![1.0_f32, 2.0, 3.0];
    let y    = vec![4.0_f32, 5.0, 6.0];
    let r    = where_fn(cond, x, y);
    println!("{:?}", r); // should print [1.0, 5.0, 3.0]
}